<?php
namespace App\Http\Controllers;
use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\Hash;
class AuthController extends Controller {public function loginForm(){return view('auth.login');}public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required']);if(Auth::attempt($d,$r->filled('remember'))){$r->session()->regenerate();return redirect()->intended('/dashboard');}return back()->withErrors(['email'=>'Email atau password salah.'])->withInput($r->only('email'));}public function registerForm(){return view('auth.register');}public function register(Request $r){$d=$r->validate(['name'=>'required|max:100','email'=>'required|email|unique:users','phone'=>'nullable|max:30','password'=>'required|min:6|confirmed']);$d['password']=Hash::make($d['password']);$d['role']='user';$u=User::create($d);Auth::login($u);return redirect('/dashboard');}public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/');}}